int count(vector<int> arr, int n)
  {
    if (n <= 0)
      return 1;
    int ans = 0;
    for (int i = 0; i < n; ++i)
    {
      if (arr[i] % n == 0 || n % arr[i] == 0)
      {
        swap(arr[i], arr[n - 1]);
        ans += count(arr, n - 1);
        swap(arr[i], arr[n - 1]);
      }
    }

    return ans;
  }

