int count(vector<int> arr, int n) {
    struct Frame {
        int n;
        int i;
        int ans;
        int state;
    };

    if (n <= 0)
        return 1;

    std::stack<Frame> stk;
    stk.push({n, 0, 0, 0});

    int final_result = 0;

    while (!stk.empty()) {
        auto& curr = stk.top();

        if (curr.n <= 0) {
            final_result = 1;
            stk.pop();
            if (!stk.empty()) {
                stk.top().ans += final_result;
                stk.top().i++;
            }
            continue;
        }

        if (curr.state == 0) {
            curr.ans = 0;
            curr.i = 0;
            curr.state = 1;
        }

        if (curr.i < curr.n) {
            int i = curr.i;
            int curr_n = curr.n;
            if (arr[i] % curr_n == 0 || curr_n % arr[i] == 0) {
                swap(arr[i], arr[curr_n - 1]);
                // Save return state by pushing next frame
                stk.push({curr_n - 1, 0, 0, 0});
                continue;
            } else {
                curr.i++;
                continue;
            }
        } else {
            int res = curr.ans;
            stk.pop();
            if (!stk.empty()) {
                // We just returned from a recursive call, swap back elements
                int parent_n = stk.top().n;
                int parent_i = stk.top().i;
                swap(arr[parent_i], arr[parent_n - 1]);

                stk.top().ans += res;
                stk.top().i++;
            } else {
                final_result = res;
            }
        }
    }

    return final_result;
}

