int power_rec(int base, int exp, int mod) {
    int res = 1;
    long long b = base;
    long long m = mod;

    // Handle base case when mod is 1
    if (m == 1) return 0;

    while (exp > 0) {
        if (exp & 1) {
            res = (res * b) % m;
        }
        b = (b * b) % m;
        exp >>= 1;
    }
    return res;
}

