int solve(vector<int>& cost, int idx) {
    int n = cost.size();
    int next1 = 0;
    int next2 = 0;
    int current = 0;

    for (int i = n - 1; i >= idx; --i) {
        int move_one = cost[i] + next1;
        int move_two = cost[i] + next2;
        current = min(move_one, move_two);
        next2 = next1;
        next1 = current;
    }

    return current;
}

