    // Using a stack to simulate the recursive tree traversal since it has branching (take and skip)
    struct State {
        int i;
        int prev;
        int stage; // 0: initial, 1: after take evaluated, 2: after skip evaluated
        int take_res;
        int skip_res;
    };

    std::stack<State> st;
    st.push({i, prev, 0, 0, 0});
    int final_result = 0;

    while (!st.empty()) {
        auto& curr = st.top();

        if (curr.i >= n) {
            int res = 0;
            st.pop();
