                    st.top().take_res = res;
                    st.top().stage = 2;
                } else {
                    st.top().skip_res = res;
                    // Both branches done for the parent
                    int parent_ans = max(st.top().take_res, st.top().skip_res);
                    st.pop();
                    if (!st.empty()) {
