int solve(int n, int p) {
    // Since the recursion is binary (branching into two choices at each step),
    // replacing it with an explicit stack is required to maintain the traversal state.
    #include <stack>

    struct State {
        int n;
        int p;
    };

    std::stack<State> st;
    st.push({n, p});

    while (!st.empty()) {
        State current = st.top();
        st.pop();

        if (current.n == 0) {
            return true;
        }

        if (std::pow(3, current.p) > current.n) {
            continue;
        }

        // Push the second branch first so the first branch is processed first
        st.push({current.n, current.p + 1});
        st.push({current.n - static_cast<int>(std::pow(3, current.p)), current.p + 1});
    }

    return false;
}

