void dfs(std::vector<int> &arr, int i, std::vector<int> &ans, int stn)
{
  struct State {
    int i;
    int stn;
    int branch;
  };

  std::stack<State> s;
  s.push({i, stn, 0});

  while (!s.empty()) {
    State curr = s.top();
    s.pop();

    if (curr.i == arr.size()) {
      ans.push_back(curr.stn);
      continue;
    }

    if (curr.branch == 0) {
      // Replace the first recursive call and queue the second branch for later
      s.push({curr.i, curr.stn, 1});
      s.push({curr.i + 1, curr.stn, 0});
    } else if (curr.branch == 1) {
      // Replace the second recursive call
