      continue;
    }

    if (!curr.initialized) {
      if (curr.i >= n) {
        stk.pop();
        continue;
      }

      curr.maxs = curr.str[curr.i];
      for (int j = curr.i + 1; j < n; j++) {
        curr.maxs = max(curr.maxs, curr.str[j]);
      }

      if (curr.maxs != curr.str[curr.i]) {
        curr.k--;
      }

      curr.j = curr.i;
      curr.initialized = true;
    }

    // Find next matching character from current j
    bool matched = false;
    while (curr.j < n) {
      int j = curr.j;
      curr.j++;
      if (curr.str[j] == curr.maxs) {
        swap(curr.str[curr.i], curr.str[j]);
        ans = max(ans, curr.str);

        // Push next state for recursion: findmax(str, ans, k, n, i + 1)
        stk.push({curr.str, curr.k, curr.i + 1, curr.i + 1, '\0', false});
        matched = true;
        break;
      }
    }

    if (!matched) {
      stk.pop();
    }
  }
}

