    struct Frame {
        int idx;
        int temp;
        int i;
    };

    std::stack<Frame> stk;
    stk.push({idx, temp, idx});

    while (!stk.empty()) {
        Frame &curr = stk.top();

        // If this is the first time visiting this frame (or we just updated result for base state),
        // update the global result for the current 'temp'.
        // To avoid redundant max checks, we can do it when entering/resuming.
        result = max(result, __builtin_popcount(curr.temp));

