#include <vector>

bool isMatch(std::string text, std::string pattern) {
    int m = text.length();
    int n = pattern.length();

    // DP table where dp[i][j] represents whether text[i:] matches pattern[j:]
    // Size the table from the arguments (+1 for the empty suffix case)
    std::vector<std::vector<bool>> dp(m + 1, std::vector<bool>(n + 1, false));

    // Base case: empty text and empty pattern match
    dp[m][n] = true;

    // Fill the table from bottom-up to avoid recomputing overlapping subproblems
    for (int i = m; i >= 0; --i) {
        for (int j = n - 1; j >= 0; --j) {
            bool first_char_matched = (i < m && (pattern[j] == text[i] || pattern[j] == '.'));

            if (j + 1 < n && pattern[j + 1] == '*') {
                dp[i][j] = dp[i][j + 2] || (first_char_matched && dp[i + 1][j]);
            } else {
                dp[i][j] = first_char_matched && dp[i + 1][j + 1];
            }
        }
    }

    return dp[0][0];
}

