char findKthBit(int n, int k) {
    bool inverted = false;

    while (n > 1) {
        int length = (1 << n) - 1;
        int mid = length / 2 + 1; // equivalent to ceil(length / 2.0)

        if (k == mid) {
            return inverted ? '0' : '1';
        } else if (k > mid) {
            k = length - (k - 1);
            inverted = !inverted;
        }
        // If k < mid, we just decrement n and keep k the same
        n--;
    }

    return inverted ? '1' : '0';
}

