int gcd(int num1, int num2) {
    if (num1 <= 0 | num2 <= 0) {
        throw std::domain_error("Euclidean algorithm domain is for ints > 0");
    }

    if (num1 == num2) {
        return num1;
    }

    // Everything divides 0
    if (num1 == 0)
        return num2;
    if (num2 == 0)
        return num1;

    // base case
    if (num1 == num2)
        return num1;

    // a is greater
    if (num1 > num2)
        return gcd(num1 - num2, num2);
    return gcd(num1, num2 - num1);
}

