long long Count(int i) {
    long long result = 0;
    while (true) {
        if (i == 0) {
            result = 1;
            break;
        } else if (i < 0) {
            result = 0;
            break;
        }

        if (a[i] != 0) {
            result = a[i];
            break;
        }

        // Since we are replacing recursion with iteration, we need to handle
        // the evaluation path iteratively or compute values bottom-up.
        // For this specific recurrence: a[i] = (i + 1) + 2 * a[i - 1].
        // Let's compute iteratively down to the base cases.
        // To keep it strictly matching the original memoized behavior for any single call:
        int current = i;
        while (current >= 0 && a[current] == 0) {
            if (current == 0) {
                a[0] = 1;
                break;
            }
            current--;
        }

        // Now fill upwards from the first uncalculated or base up to i
        for (int j = 1; j <= i; ++j) {
            if (a[j] == 0) {
                a[j] = (j + 1) + 2 * a[j - 1];
            }
        }

        result = a[i];
        break;
    }
    return result;
}

