int longest_palindromic_substr(string str) {
    int n = str.length();
    if (n == 0) return 0;

    // dp[i][j] stores the length of the longest palindromic substring in str[i...j]
    vector<vector<int>> dp(n, vector<int>(n, 0));

    for (int i = 0; i < n; ++i) {
        dp[i][i] = 1;
    }

    for (int cl = 2; cl <= n; ++cl) {
        for (int i = 0; i < n - cl + 1; ++i) {
            int j = i + cl - 1;
            if (str[i] == str[j] && cl == 2) {
                dp[i][j] = 2;
            } else if (str[i] == str[j]) {
                dp[i][j] = dp[i + 1][j - 1] + 2;
            } else {
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1]);
            }
        }
    }

    return dp[0][n - 1];
}

