void get_option_states(const vector<int>& options, int index, int k, int state,
                           vector<int>& res){

        struct Frame {
            int index;
            int k;
            int state;
            int i;
        };

        if (k == 0) {
            res.push_back(state);
            return;
        }
        if (index == options.size()) return;

        std::stack<Frame> stk;
        // Push the initial state for the loop starting at 'index'
        stk.push({index, k, state, index});

        while (!stk.empty()) {
            Frame& curr = stk.top();

            if (curr.i >= options.size()) {
                stk.pop();
                if (!stk.empty()) {
                    stk.top().i++;
