using namespace std;

void grayCodeUtil(vector<int>& res, int n, int& num) {
    // Replaced direct self-recursion with an iterative loop using an explicit stack
    // to simulate the two recursive branches and the intermediate state.
    struct Frame {
        int n;
        int state;
    };

    if (n <= 0) {
        res.push_back(num);
        return;
    }

    vector<Frame> stack;
    stack.push_back({n, 0});

    while (!stack.empty()) {
        auto& current = stack.back();

        if (current.n == 0) {
            res.push_back(num);
            stack.pop_back();
            continue;
        }

        if (current.state == 0) {
            current.state = 1;
