void subsetSum(vector<int>& c, int& ans) {
    int L = c.size();
    int mul = (int)pow(2, L - 1);
    for(int i = 0; i < c.size(); i++) ans += c[i] * mul;
}

void subsetGen(int* arr, int i, int n, int& ans, vector<int>& c) {
    // Since subsetGen features multiple branching (tree recursion: exclude and include),
    // an explicit stack is required to replace the recursion without changing the behavior or signature.
    struct Frame {
        int index;
        int state; // 0: before excluding, 1: before including
    };

    vector<Frame> stack;
    stack.push_back({i, 0});

    while (!stack.empty()) {
        Frame& curr = stack.back();

        if (curr.index == n) {
            subsetSum(c, ans);
            stack.pop_back();
            continue;
        }

        if (curr.state == 0) {
            curr.state = 1;
            stack.push_back({curr.index + 1, 0});
        } else if (curr.state == 1) {
            curr.state = 2;
            c.push_back(arr[curr.index]);
            stack.push_back({curr.index + 1, 0});
        } else {
            c.pop_back();
            stack.pop_back();
        }
    }
}

