using namespace std;
#include <vector>
#include <cmath>

int numberOfWays(int n, int k) {
    // DP table dimensions: (n + 1) x (k + 1), initialized to -1 for memoization
    vector<vector<long long>> memo(n + 1, vector<long long>(k + 1, -1));

    auto dp = [&](auto& self, int curr_n, int curr_k) -> long long {
        if (curr_n == 0) return 1;
        if (curr_k == 0) return 1;
        if (memo[curr_n][curr_k] != -1) return memo[curr_n][curr_k];

        // Safe computation of pow(2, curr_k) with overflow prevention
        double p = std::pow(2.0, curr_k);
        long long ways = 0;
        if (p <= curr_n) {
            int curr_val = static_cast<int>(p);
            ways = self(self, curr_n - curr_val, curr_k) + self(self, curr_n, curr_k - 1);
        } else {
            ways = self(self, curr_n, curr_k - 1);
        }

        return memo[curr_n][curr_k] = ways;
    };

    return static_cast<int>(dp(dp, n, k));
}

