int sqrtSearch(int low, int high, int N) {
    while (low <= high) {
        int mid = low + (high - low) / 2;

        // Use long long for multiplication to prevent potential integer overflow
        long long mid_sq = static_cast<long long>(mid) * mid;
        long long next_sq = static_cast<long long>(mid + 1) * (mid + 1);

        if (mid_sq <= N && next_sq > N) {
            return mid;
        }
        else if (mid_sq < N) {
            low = mid + 1;
        }
        else {
            high = mid - 1;
        }
    }
    return low;
}

