int calculate(int pos_start, int prev_start, int sum_start, vector<int>& v) {
    int pos = pos_start;
    int prev = prev_start;
    int sum = sum_start;

    // We use a stack-like state simulation for the recursive backtracking loop
    // Since the recursion branches on 'i' from 'prev' to 9, we need to track
    // the loop variable 'i' for each level.
    vector<int> i_stack(v.size() + 1);
    int level = pos;
    i_stack[level] = prev;

    while (level >= pos_start) {
        if (level == v.size()) {
            if (isSquare(sum)) {
                return 1;
            }
            // Backtrack
            level--;
            if (level >= pos_start) {
                int old_i = i_stack[level];
                sum -= old_i * old_i;
                i_stack[level] = old_i + 1;
            }
            continue;
        }

        int i = i_stack[level];
        if (i <= 9) {
            v[level] = i;
            sum += i * i;
            // Move to next level
            level++;
            if (level <= v.size()) {
                i_stack[level] = i;
            }
        } else {
            // Backtrack
            level--;
            if (level >= pos_start) {
                int old_i = i_stack[level];
                sum -= old_i * old_i;
                i_stack[level] = old_i + 1;
            }
        }
    }
    return 0;
}

