bool isWinning(int pos) {
  if (pos <= 0)
    return false;

  // Using a bottom-up iterative approach with a vector to store results
  // up to the target position, avoiding recursion entirely.
  std::vector<bool> dp(pos + 1, false);

  int moves[3] = { 1, 3, 4 };

  for (int i = 1; i <= pos; ++i) {
    for (int m = 0; m < 3; ++m) {
      if (i >= moves[m] && !dp[i - moves[m]]) {
        dp[i] = true;
        break;
      }
    }
  }

  return dp[pos];
}

