void get_next(int m, int state, int index, int next_state,
                  vector<int>& next){
        // Using an explicit std::stack to manage traversal state iteratively
        // since the recursion branches out via a loop.
        struct Frame {
            int index;
            int state;
            int next_state;
        };

        std::stack<Frame> stk;
        stk.push({index, state, next_state});

        while (!stk.empty()) {
            Frame current = stk.top();
            stk.pop();

            if (current.index == m) {
                next.push_back(current.next_state);
                continue;
            }

            // Push in reverse order if necessary, but standard stack push
            // processes colors from 0 to 2 (last pushed is processed first,
            // so we push color 2 down to 0 to maintain original order).
            for (int color = 2; color >= 0; --color) {
                if (color != current.state % 3) {
                    if (current.index > 0 && color == current.next_state % 3)
                        continue;
                    stk.push({current.index + 1, current.state / 3, current.next_state * 3 + color});
                }
            }
        }
    }

