#include <vector>
#include <algorithm>

int getTotalNumberOfSequences(int m, int n) {
    if (m < n) return 0;
    if (n == 0) return 1;

    // dp[i][j] will store the number of valid sequences of length j with elements <= i
    // Dimensions: (m + 1) x (n + 1)
    std::vector<std::vector<long long>> dp(m + 1, std::vector<long long>(n + 1, 0));

    for (int i = 0; i <= m; ++i) {
        dp[i][0] = 1;
    }

    for (int j = 1; j <= n; ++j) {
        for (int i = 1; i <= m; ++i) {
            if (i < j) {
                dp[i][j] = 0;
            } else {
                // dp[i-1][j] corresponds to not using 'i'
                // dp[i/2][j-1] corresponds to using 'i' as the last element
                dp[i][j] = dp[i - 1][j] + dp[i / 2][j - 1];
            }
        }
    }

    return dp[m][n];
}

