#include <iostream>
using namespace std;

int countSolutions(int n, int val) {
    if (n <= 0) return 0;
    if (n == 1) return (val >= 0) ? 1 : 0;

    // Using an explicit stack to simulate the multi-branch recursion
    // Each stack frame stores: {n, val, current_i, accumulated_total}
    struct Frame {
        int n;
        int val;
        int i;
        int total;
    };

    std::stack<Frame> stk;
    stk.push({n, val, 0, 0});

    int final_result = 0;

    while (!stk.empty()) {
        auto& current = stk.top();

        if (current.n == 1) {
            int res = (current.val >= 0) ? 1 : 0;
            stk.pop();
            if (!stk.empty()) {
                stk.top().total += res;
            } else {
                final_result += res;
            }
            continue;
        }

        if (current.i <= current.val) {
            int next_n = current.n - 1;
            int next_val = current.val - current.i;
            current.i++; // prepare for the next iteration when we return

            // Base case optimization or push new frame
            if (next_n == 1) {
                int res = (next_val >= 0) ? 1 : 0;
                current.total += res;
            } else {
                stk.push({next_n, next_val, 0, 0});
            }
        } else {
            int res = current.total;
            stk.pop();
            if (!stk.empty()) {
                stk.top().total += res;
            } else {
                final_result += res;
            }
        }
    }

    return final_result;
}

