using namespace std;

void checkUntil(int start_num, int K, int N, vector<int>& ans) {
    if (N == 1) {
        ans.push_back(start_num);
        return;
    }

    struct State {
        int num;
        int n;
        int branch;
    };

    stack<State> s;
    s.push({start_num, N, 0});

    while (!s.empty()) {
        State current = s.top();
        s.pop();

        if (current.n == 1) {
            ans.push_back(current.num);
            continue;
        }

        int last_digit = current.num % 10;

        if (current.branch == 0) {
            // Push second branch so it gets processed after the first branch
            if (K != 0) {
                if ((last_digit - K) >= 0) {
                    s.push({current.num, current.n, 1});
                }
            }
            // Process first branch immediately
            if ((last_digit + K) <= 9) {
                s.push({10 * current.num + (last_digit + K), current.n - 1, 0});
            }
        } else if (current.branch == 1) {
            if ((last_digit - K) >= 0) {
                s.push({10 * current.num + last_digit - K, current.n - 1, 0});
            }
        }
    }
}

