void dfs(int start_node, int start_parent) {
    struct Frame {
        int node;
        int parent;
        size_t edge_idx;
        bool visiting_children;
    };

    stack<Frame> st;
    st.push({start_node, start_parent, 0, false});

    while (!st.empty()) {
        Frame& curr = st.top();

        if (!curr.visiting_children) {
            curr.visiting_children = true;
            curr.edge_idx = 0;
        }

        if (curr.edge_idx < graph[curr.node].size()) {
            int to = graph[curr.node][curr.edge_idx];
            curr.edge_idx++;

            if (to == curr.parent) continue;

            st.push({to, curr.node, 0, false});
        } else {
            int node = curr.node;
            int parent = curr.parent;
            st.pop();

            if (parent != -1) {
                weight[parent] += weight[node];
            }
        }
    }
}

