#include <algorithm>
#include <vector>
using namespace std;

int maxProd(int N) {
    if (N == 0) return 1;
    if (N < 10) return N;

    // Convert N to string to know the number of digits
    string s = to_string(N);
    int len = s.length();

    // Memoization table or iterative DP can be implemented.
    // Since the state space depends on the prefix values and constraints of N,
    // a standard digit DP approach is suitable.
    // Here we use a helper lambda with memoization for overlapping subproblems.

    // For a simple top-down memoization, we can store results in a hash map or vector.
    // Given N can be up to standard int limits, digit DP over the digits of N is efficient.

    vector<int> digits;
    int temp = N;
    while (temp > 0) {
        digits.push_back(temp % 10);
        temp /= 10;
    }
    reverse(digits.begin(), digits.end());

    // digit DP state: (index, is_less, is_started)
    // But since the original recurrence specifically uses N/10 and N/10 - 1 with specific patterns,
    // we can use a hash map for memoizing the original function signature `maxProd(int)`.

    // Using a static or local unordered_map for memoisation:
    static unordered_map<int, int> memo;

    auto dp = [&](auto& self, int n) -> int {
        if (n == 0) return 1;
        if (n < 10) return n;
        if (memo.find(n) != memo.end()) return memo[n];

        int res = max(self(self, n / 10) * (n % 10), self(self, n / 10 - 1) * 9);
        return memo[n] = res;
    };

    return dp(dp, N);
}

