using namespace std;

int calculate(int pos, int prev, int left, int k) {
    // Since the recursion branches multiple times in the loop, 
    // an explicit std::stack is required to maintain the traversal state.
    #include <stack>
    struct State {
        int pos;
        int prev;
        int left;
        int i;
        int answer;
        int phase;
    };

    int final_answer = 0;
    stack<State> s;
    s.push({pos, prev, left, prev, 0, 0});

    while (!s.empty()) {
        State& curr = s.top();

        if (curr.pos == k) {
            int ret = (curr.left == 0) ? 1 : 0;
            s.pop();
            if (!s.empty()) {
                s.top().answer += ret;
            } else {
                final_answer += ret;
            }
            continue;
        }

        if (curr.left == 0) {
            int ret = 0;
            s.pop();
            if (!s.empty()) {
                s.top().answer += ret;
            } else {
                final_answer += ret;
            }
            continue;
        }

        if (curr.i <= curr.left) {
            int next_pos = curr.pos + 1;
            int next_prev = curr.i;
            int next_left = curr.left - curr.i;
            curr.i++;
            s.push({next_pos, next_prev, next_left, next_prev, 0, 0});
        } else {
            int ret = curr.answer;
            s.pop();
            if (!s.empty()) {
                s.top().answer += ret;
            } else {
                final_answer += ret;
            }
        }
    }
    return final_answer;
}

int countWaystoDivide(int n, int k) {
    return calculate(0, 1, n, k);
}

