long long countOfNumbers(int digit, int prev1, int prev2, int N) {
    // Iterative approach using bottom-up DP to eliminate recursion entirely
    // since the original function computes states from digit=1 up to N+1.
    // We populate the table iteratively to ensure identical results and signature.

    // If already computed or base case reached:
    if (digit == N + 1) return 1;
    if (dp[digit][prev1][prev2] != -1) return dp[digit][prev1][prev2];

    // Initialize all states that might be needed or compute bottom-up.
    // Since the original code is top-down memoized recursion, we can simulate 
    // the exact state evaluation order or use a bottom-up loop from N down to 1.

    for (int d = N + 1; d >= 1; --d) {
        if (d == N + 1) continue;
        // We need to iterate over all valid prev1 and prev2 for this digit
        int max_p1 = (d == 1) ? 0 : 9; // Based on usage, prev1 at d=1 is passed as some initial value
        int min_p1 = 0;
        int max_p2 = 9;
        int min_p2 = 0;

        for (int p1 = min_p1; p1 <= max_p1; ++p1) {
            for (int p2 = min_p2; p2 <= max_p2; ++p2) {
                if (dp[d][p1][p2] != -1) continue;

                long long sum = 0;
                if (d == 1) {
                    for (int j = (N == 1 ? 0 : 1); j <= 9; ++j) {
                        sum += dp[d + 1][j][p1];
                    }
                } else if (d == 2) {
                    for (int j = 0; j <= 9; ++j) {
                        sum += dp[d + 1][j][p1];
                    }
                } else {
                    for (int j = 0; j <= abs(p1 - p2); ++j) {
                        sum += dp[d + 1][j][p1];
                    }
                }
                dp[d][p1][p2] = sum;
            }
        }
    }

    return dp[digit][prev1][prev2];
}

