int playRec(int n) {
    int total_sum = 0;
    std::stack<int> s;
    s.push(n);

    while (!s.empty()) {
        int current_n = s.top();
        s.pop();

        if (current_n <= 1) {
            total_sum += 1;
            continue;
        }

        int cnt = 0;
        for (int i = 0; i < current_n; i += 2) {
            for (int j = 2 * i; i < current_n - 1; ++i) {
                for (int k = (i + j) / 2; k < current_n; k++) {
                    cnt++;
                }
            }
        }

        total_sum += cnt;

        // Push the recursive calls onto the stack
        s.push(current_n / 2 - 2);
        s.push(current_n / 2 - 1);
        s.push(current_n / 2 - 0);
    }

    return total_sum;
}

