    st.push({n, k});

    while (!st.empty()) {
        auto [curr_n, curr_k] = st.top();

        if (hash[curr_n][curr_k] != 0) {
            st.pop();
            continue;
        }

        bool left_ready = (hash[curr_n - 1][curr_k + 1] != 0);
        bool right_ready = (hash[curr_n - 1][curr_k] != 0);

        if (!left_ready) {
