using namespace std;
#include <vector>

int Hosoya(int n, int m) {
    if (n < 0 || m < 0 || m > n) return 0;

    // Use a DP table sized dynamically from the arguments n and m.
    // Since values depend on (n-1, m), (n-2, m), etc., we use a 2D table of size (n+1) x (m+1).
    vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));

    for (int i = 0; i <= n; ++i) {
        for (int j = 0; j <= min(i, m); ++j) {
            if ((i == 0 && j == 0) || (i == 1 && j == 0) || (i == 1 && j == 1) || (i == 2 && j == 1)) {
                dp[i][j] = 1;
            } else if (i > j) {
                int val1 = (i - 1 >= j) ? dp[i - 1][j] : 0;
                int val2 = (i - 2 >= j) ? dp[i - 2][j] : 0;
                dp[i][j] = val1 + val2;
            } else if (j == i) {
                int val1 = (i - 1 >= j - 1 && j - 1 >= 0) ? dp[i - 1][j - 1] : 0;
                int val2 = (i - 2 >= j - 2 && j - 2 >= 0) ? dp[i - 2][j - 2] : 0;
                dp[i][j] = val1 + val2;
            } else {
                dp[i][j] = 0;
            }
        }
    }

    return dp[n][m];
}

