improved_code:
void perm(int i, int n, int vis[], int cur[])
{
    // We need an explicit stack to maintain the state of the DFS/backtracking loop
    // because this is not simple tail recursion—each level of recursion branches
    // into a loop over 'j' and requires backtracking state restoration.
    struct Frame {
        int i;
        int j;
    };

    if (i >= n) return;

    std::vector<Frame> stack;
    stack.reserve(n);

    // Push initial frame for level i
    stack.push_back({i, 0});

    while (!stack.empty()) {
        auto& current = stack.back();
        int depth = current.i;

        if (depth == n) {
            // print
            stack.pop_back();
            if (!stack.empty()) {
                // Backtrack the previous choice
                int prev_i = stack.back().i;
                int prev_j = stack.back().j - 1; // It was incremented, or we look at cur[prev_i]
                vis[cur[prev_i]] = 0;
                stack.back().j++; // Move to next iteration for next time
            }
            continue;
        }

        // Find the next available unvisited 'j'
        bool found = false;
        for (; current.j < n; ++current.j) {
            int j = current.j;
            if (!vis[j]) {
                vis[j] = 1;
                cur[depth] = j;
                found = true;

                // Prepare to push next level, but increment current.j first so when we return, we check the next j
                current.j++; 
                stack.push_back({depth + 1, 0});
                break;
            }
        }

        if (!found) {
            // Exhausted choices at this level, pop and backtrack
            stack.pop_back();
            if (!stack.empty()) {
                int prev_i = stack.back().i;
                // The element we set at prev_i is cur[prev_i]
                vis[cur[prev_i]] = 0;
            }
        }
    }
}

