int BinomialCoefficient(int n, int k) {
  if (n < k) {
    return 0;
  }
  if (k == 0 || k == n) {
    return 1;
  }
  // Build Pascal's triangle rows up to n, taking only k+1 columns.
  // Allocate the table based on the arguments (no fixed-size constant).
  std::vector<std::vector<int>> table(n + 1, std::vector<int>(k + 1, 0));
  for (int i = 0; i <= n; ++i) {
    for (int j = 0; j <= std::min(i, k); ++j) {
      if (j == 0 || j == i) {
        table[i][j] = 1;
      } else {
        table[i][j] = table[i - 1][j - 1] + table[i - 1][j];
      }
    }
  }
  return table[n][k];
}

