int seriesSum(int calculated, int current, int N) {
    int sum = 0;
    while (current != N + 1) {
        int cur = 1;
        int i;
        for (i = calculated; i < calculated + current; i++)
            cur *= i;
        sum += cur;
        calculated = i;
        current = current + 1;
    }
    return sum;
}

