int f(int n, int start){
    int acc = 0; // accumulator for XOR
    while (start % 2 != 0) {
        acc ^= (start - 1);
        n = n + 1;
        start = start - 1;
    }
    // now start is even
    int base = (n % 2) ? (((n / 2) & 1) ^ (start + n - 1)) : ((n / 2) & 1);
    return base ^ acc;
}

