int printCountRec(int dist) {
    if (dist < 0) return 0;
    if (dist == 0) return 1;
    vector<int> dp(dist + 1, 0);
    dp[0] = 1;
    for (int i = 1; i <= dist; ++i) {
        dp[i] = dp[i-1];
        if (i >= 2) dp[i] += dp[i-2];
        if (i >= 3) dp[i] += dp[i-3];
    }
    return dp[dist];
}

